@njit
def stress_sim(arr,t,k):
 out=np.empty(len(arr));out[0]=arr[0,0]
 for i in range(len(arr)-1):
  p=out[i];v,q=arr[i,1:3];k1=rhs(p,v,q,t,k);k2=rhs(p+2.5*k1,v,q,t,k);k3=rhs(p+2.5*k2,v,q,t,k);k4=rhs(p+5*k3,v,q,t,k)
